use xiom.io;

type Player = {
  name: Str;
  number: Int;
  position: Str;
}

type Team = {
  name: Str;
  sport: Str;
  star: Player;
}

fn announce(p: Player) -> Str {
  return "Number " + p.number + ", playing " + p.position + " — " + p.name + "!";
}

fn same_sport(a: Team, b: Team) -> Bool {
  return a.sport == b.sport;
}

fn main() -> Int {
  let p1 = Player{ name: "Messi"; number: 10; position: "Forward"; };
  let p2 = Player{ name: "Ronaldo"; number: 7; position: "Forward"; };
  let team1 = Team{ name: "Barcelona"; sport: "Football"; star: p1; };
  let team2 = Team{ name: "Madrid"; sport: "Football"; star: p2; };
  if same_sport(team1, team2) { return 1; }
  return 0;
}
